1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
8	  const [x, y] = cell;
9	  const [candidateX, candidateY] = candidate;
10	  const isTouching =
11	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
12	  return isTouching && !isSameCell(cell, candidate);
13	}
14	
15	function countLivingNeighbours(cell: Cell, livingCells: Cell[]): number {
16	  return livingCells.filter((candidate) => isNeighbourOf(cell, candidate))
17	    .length;
18	}
19	
20	function survives(cell: Cell, livingCells: Cell[]): boolean {
21	  const livingNeighbours = countLivingNeighbours(cell, livingCells);
22	  return livingNeighbours === 2 || livingNeighbours === 3;
23	}
24	
25	function isBorn(cell: Cell, livingCells: Cell[]): boolean {
26	  return countLivingNeighbours(cell, livingCells) === 3;
27	}
28	
29	function neighboursOf([x, y]: Cell): Cell[] {
30	  const offsets = [-1, 0, 1];
31	  return offsets.flatMap((dx) =>
32	    offsets
33	      .filter((dy) => !(dx === 0 && dy === 0))
34	      .map((dy): Cell => [x + dx, y + dy]),
35	  );
36	}
37	
38	export function nextGeneration(livingCells: Cell[]): Cell[] {
39	  const survivors = livingCells.filter((cell) => survives(cell, livingCells));
40	
41	  const deadNeighbours = livingCells
42	    .flatMap(neighboursOf)
43	    .filter(
44	      (candidate) =>
45	        !livingCells.some((living) => isSameCell(living, candidate)),
46	    );
47	  const births = deadNeighbours.filter(
48	    (cell, index) =>
49	      isBorn(cell, livingCells) &&
50	      deadNeighbours.findIndex((other) => isSameCell(other, cell)) === index,
51	  );
52	
53	  return [...survivors, ...births];
54	}
