export function nextGeneration(livingCells: Cell[]): Cell[] {
  const survivors = livingCells.filter((cell) => survives(cell, livingCells));

  const deadNeighbours = livingCells
    .flatMap(neighboursOf)
    .filter(
      (candidate) =>
        !livingCells.some((living) => isSameCell(living, candidate)),
    );
  const births = deadNeighbours.filter(
    (cell, index) =>
      isBorn(cell, livingCells) &&
      deadNeighbours.findIndex((other) => isSameCell(other, cell)) === index,
  );

  return [...survivors, ...births];
}

